effect.shader:
const vec3 kY = vec3(0.299, 0.587, 0.114);
const vec3 kI = vec3(0.596, -0.275, -0.321);
const vec3 kQ = vec3(0.212, -0.523, 0.311);
vec3 rgb2yiq(vec3 rgb) {
return vec3(dot(rgb, kY), dot(rgb, kI), dot(rgb, kQ));
}
vec3 yiq2rgb(vec3 yiq) {
vec3 rgb;
rgb.r = yiq.x + 0.956 * yiq.y + 0.621 * yiq.z;
rgb.g = yiq.x - 0.272 * yiq.y - 0.647 * yiq.z;
rgb.b = yiq.x - 1.105 * yiq.y + 1.702 * yiq.z;
return rgb;
}
vec3 getBlur(vec2 uv, float radius) {
vec2 off = vec2(radius) / acScreenSize;
vec3 acc = texture2DCv(inputImg.texture, uv + vec2(-off.x, -off.y)).rgb;
acc += texture2DCv(inputImg.texture, uv + vec2( off.x, -off.y)).rgb;
acc += texture2DCv(inputImg.texture, uv + vec2(-off.x,  off.y)).rgb;
acc += texture2DCv(inputImg.texture, uv + vec2( off.x,  off.y)).rgb;
return acc * 0.25;
}
void main() {
vec2 uv = acScreenNorm;
vec3 c0 = texture2DCv(inputImg.texture, uv).rgb;
float s = smallDetailSize;
vec3 bTiny  = getBlur(uv, s * 0.5);
vec3 bSmall = getBlur(uv, s * 1.0);
vec3 bMed   = getBlur(uv, s * 2.0);
vec3 bLarge = getBlur(uv, s * 4.0);
vec3 dTiny  = c0 - bTiny;
vec3 dSmall = bTiny - bSmall;
vec3 dMed   = bSmall - bMed;
vec3 dLarge = bMed - bLarge;
vec3 detail = dTiny * scaleTiny
+ dSmall * scaleSmall
+ dMed * scaleMedium
+ dLarge * scaleLarge;
float detailLuma = dot(abs(detail), kY);
float gate = smoothstep(edgeThreshold, edgeThreshold + 0.05, detailLuma);
detail *= gate;
vec3 detailYIQ = rgb2yiq(detail);
detailYIQ.x *= sharpenLuma;
detailYIQ.y *= sharpenChroma;
detailYIQ.z *= sharpenChroma;
detail = yiq2rgb(detailYIQ);
detail *= vec3(sharpenRed, sharpenGreen, sharpenBlue);
vec3 result = c0 + detail * sharpenAmp;
gl_FragColor = vec4(result, 1.0);
}
